def transform(grid):
    out=[row[:] for row in grid]
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2]
    # Join each point to its nearest point with an L-shaped 3-colored path,
    # choosing the horizontal segment at the lower of the pair's rows.
    remaining=set(pts)
    edges=[]
    while len(remaining)>1:
        best=None
        for a in remaining:
            for b in pts:
                if b in remaining or b==a: continue
                d=abs(a[0]-b[0])+abs(a[1]-b[1])
                if best is None or d<best[0]: best=(d,a,b)
        if best is None: break
        _,a,b=best; remaining.remove(a); edges.append((a,b))
    for (r,c),(rr,cc) in edges:
        # use horizontal along the row of the lower endpoint
        y=max(r,rr)
        for x in range(min(c,cc),max(c,cc)+1):
            if out[y][x]==0: out[y][x]=3
        for z in range(min(r,rr),max(r,rr)+1):
            if out[z][cc]==0: out[z][cc]=3
    return out
